// TH15 synthetic bullet aliases copied from transcribe/th15/touhou-bullets.ecl.
// Only the entries this card's source actually uses are declared.
const TH15_RING_BALL2: int = 464;   // source type 7, base radius 4, colors 0-15

// TH15 Stage 3 wave (th15_s3_w05).
// Source: st03.ecl.txt MainSub03:1437-1453 (entry, reward formation of 8 GirlD01)
//         st03.ecl.txt GirlD01:841-865, GirlD01_at:867-913 (dependencies).
// Card frame 0 == source MainSub03 entry; the source attack starts after OPENING_BUFFER.
// Chapter gate [-9905]==4 and the enmCreateF boss0 gate are dropped per the approved
// chapter/gating simplification, so all eight planned creates execute.

const TIME_LIMIT: int = 2824;      // 120 opening + 2700 window + 4 startup margin
const OPENING_BUFFER: int = 120;

// GirlD01_at wave shape, source lines 874-909, rank 0..3 = Easy/Normal/Hard/Lunatic.
//   roads   = etCount first arg: 5 / 10 / 10 / 10   (layers always 17)
//   speed0  = etSpeed first arg: 2.6 / 2.6 / 3.2 / 3.5, second arg 1.8
//   volleys = diffI(A): 2 / 4 / 6 / 6
//   gap     = wait after each etOn: 125 / 125 / 90 / 90
const LAYERS: int = 17;
const LAYER_DELTA: int = 273;      // etAngle spread 0.02617994 rad = 1.5 deg in BAM
const SPEED_END: fx = 1.8fx;

async sub girl_at() {
    wait(60);                                   // GirlD01_at:0870
    var rank: int = global(GVAR_RANK);
    var roads: int = 10;
    var speed0: fx = 3.5fx;
    var volleys: int = 6;
    var gap: int = 90;
    if rank == 0 {
        roads = 5;
        speed0 = 2.6fx;
        volleys = 2;
        gap = 125;
    } else if rank == 1 {
        speed0 = 2.6fx;
        volleys = 4;
        gap = 125;
    } else if rank == 2 {
        speed0 = 3.2fx;
    }
    // Source keeps one configured emitter and calls etOn `volleys` times; the aim
    // angle A is re-read at every etOn, so sh_aim resolves it at each sh_fire.
    sh_reset(0);
    sh_sprite(0, TH15_RING_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, roads, 1);
    for v in 0..volleys {
        // etAim mode 9 (aimed alternating-layer ring), layers outer, roads inner:
        //   angle = A + alpha + (-1)^q * (R(i) + H(M,q))
        //   speed = s0 + (s1-s0) * k/(M-1), k = (q + M%2) & ~1
        // A full ring with offset +h and one with offset -h hold the same point set as
        // the source's forward/backward road order, so each layer is one ring shot.
        for q in 0..LAYERS {
            var k: int = ((q + 1) / 2) * 2;
            var h: int = ((q + 1) / 2) * LAYER_DELTA;
            var speed: fx = speed0 + (SPEED_END - speed0) * (k as fx) / 16fx;
            if q % 2 != 0 {
                sh_angle(0, (0 - h) as angle, 0deg);
            } else {
                sh_angle(0, h as angle, 0deg);
            }
            sh_speed(0, speed, 0fx);
            // etEx type 2 (ANIM) a=1: bullet spawns displaced back by 4*velocity.
            sh_dist(0, 0fx - 4fx * speed);
            sh_fire(0);
        }
        wait(gap);                              // GirlD01_at:0898-0909
    }
}

async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);                          // setHurtbox(32,32) -> radius 16
    set_hitbox(12fx);                           // setHitbox(24,24) -> radius 12
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);     // moveVel(pi/2, 2.5)
    move_vel(70, 90deg, 0fx, EASE_QUAD_IN);     // moveVelTime(70, mode1, pi/2, 0)
    spawn girl_at();                            // @GirlD01_at() async
    wait(80);
    move_speed(120, 0.2fx, EASE_QUAD_IN);       // moveSpeedTime(120, mode1, 0.2)
    wait(400);
    move_speed(120, 3.0fx, EASE_QUAD_IN);       // moveSpeedTime(120, mode1, 3.0)
    loop { wait(1000); }                        // GirlD01:0860-0863 idle tail
}

// MainSub03:1437-1453 schedule: wait 40, then four 440-frame rounds of
// (+96,-24) then (-96,-24); the source loop runs exactly four times.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(40);
    for round in 0..4 {
        _ = spawn_enemy(96fx, -24fx, 1200, 0, 1000, 0, girl);
        wait(220);
        _ = spawn_enemy(-96fx, -24fx, 1200, 0, 1000, 0, girl);
        wait(220);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
